    fn bind_profile(
        peer: HostAuthorityPeerChannel,
        material: &OriginalCellQ24MaterialReceiptConfigV1,
        dataset: &OriginalCellQ24MaterialCommandReceiptV1,
        context: ReadProfile,
    ) -> Result<Self, Error> {
