    pub(super) fn from_original_profile(
        cell: PublishedCircuitCellOwnerV1<C>,
        source: CircuitTaskSourceReadbackV1<S>,
        identity: AgentdIdentity,
        context: ReadProfile,
    ) -> Result<Self, Error> {
        let started_at = now()?;
        let binding = context.binding(started_at)?;
        let owner = Self {
