    pub(crate) fn serve_original_retained_channel(
        &self,
        channel: &mut HostAuthorityPeerChannel,
    ) -> Result<u64, Error> {
        if wire::mode(self.context.legacy()?)? != wire::Mode::Selection {
            return Err(Error::Binding(
                "retained Version Selection-only read purpose",
            ));
        }
        self.serve_channel(channel)
    }

    /// The evaluated Version host may only serve its actual four-cut profile.
    /// The pre-held original channel is retained; no stream is reconnected.
    pub(crate) fn serve_original_evaluated_retained_channel(
        &self,
        channel: &mut HostAuthorityPeerChannel,
    ) -> Result<u64, Error> {
        if !matches!(&self.context, ReadProfile::Evaluated(_))
            || self.context.mode()? != wire::Mode::Selection
        {
            return Err(Error::Binding(
                "evaluated retained Version Selection-only read purpose",
            ));
        }
        self.serve_channel(channel)
    }

    pub(super) fn serve_channel(
        &self,
        channel: &mut HostAuthorityPeerChannel,
    ) -> Result<u64, Error> {
        for request_id in 1..=128 {
            let mut failure = None;
            let exchanged = channel.exchange(|bytes| {
                self.response(bytes, request_id).map_err(|error| {
                    failure = Some(error);
                    HostIssuerTransportError::InvalidRequest
                })
            });
            match exchanged {
                Ok(true) => {}
                Ok(false) => return Ok(request_id - 1),
                Err(error) => return Err(failure.unwrap_or(Error::Transport(error))),
            }
        }
        Err(Error::Unavailable)
    }

    /// One Selection response for the concrete local Version lane. The
    /// Version brackets this actual original read with its full current checks.
    pub(crate) fn original_evaluated_selection_response(
        &self,
        expected: &crate::OriginalCircuitEvaluatedRetentionContextV1,
        bytes: &[u8],
        request_id: u64,
    ) -> Result<Vec<u8>, Error> {
        let ReadProfile::Evaluated(context) = &self.context else {
            return Err(Error::Binding("local evaluated Selection-only read purpose"));
        };
        if self.context.mode()? != wire::Mode::Selection {
            return Err(Error::Binding("local evaluated Selection-only read purpose"));
        }
        context.require_original_selection(expected)?;
        self.response(bytes, request_id)
    }

    /// One readonly response for the original Version's five-cut C reader.
    /// The concrete Version serving lane brackets this with its actual full
    /// predecessor/publication observations under the same Version state lock.
    pub(crate) fn original_evaluated_next_use_response(
        &self,
        bytes: &[u8],
        request_id: u64,
    ) -> Result<Vec<u8>, Error> {
        self.require_original_evaluated_next_use_profile()?;
        self.response(bytes, request_id)
    }

    /// The distinct readiness response still performs only the original C
