            material,
            initial_binding,
            RetainedVersionOriginV1::Recovered,
            purpose,
            RetainedVersionHostStateV1 {
                dataset,
                initial_trainer: Some(trainer),
                trainer: None,
                initial_evaluator: evidence.into_evaluator(),
                evaluator: None,
                shared_evaluated: None,
                cut: None,
